// A stand-in for the SDK's stdio transport, at the path the plugin derives from
// its `sdkPath` (`new URL('./stdio.js', sdkPath)`), so the per-agent connection
// mode can be exercised without spawning anything.
//
// Every construction is recorded: a test asserts ONE connection per agent, and
// reads the command, args and cwd each was given.

export const spawned = []

/** The transport instances themselves, so a test can assert they were closed. */
export const instances = []

export class StdioClientTransport {
  constructor (options) {
    this.options = options
    this.closed = false
    spawned.push(options)
    instances.push(this)
  }

  async start () {}

  async close () {
    this.closed = true
  }
}
